import math

def priority(task, state, w_type=1.0, w_weight=0.5, w_tenant=0.2, w_spt=0.1, late_pen=10.0):
    if task.task_type == 'variant_calling':
        c = 5.0
    elif task.task_type == 'sv_calling':
        c = 3.0
    else:
        c = 1.0
    slack = task.due - state.now - task.estimated_runtime
    p = max(task.estimated_runtime, 1e-6)
    if slack < 0:
        base = -late_pen + w_spt / p
    else:
        base = -slack
    bonus = w_type * c + w_weight * task.weight
    if task.tenant == 'premium':
        bonus += w_tenant
    return base + bonus
```

