import math

def priority(task, state, w_type=1.0, w_weight=0.5, w_tenant=0.2, w_spt=0.1, late_pen=10.0, load_thresh=1.0, load_scale=2.0):
    if task.task_type == 'variant_calling':
        c = 5.0
    elif task.task_type == 'sv_calling':
        c = 3.0
    else:
        c = 1.0
    slack = task.due - state.now - task.estimated_runtime
    p = max(task.estimated_runtime, 1e-6)
    load = state.queue_work / max(state.capacity * max(state.mean_est, 1e-6), 1e-6)
    penalty = late_pen * (1.0 + load_scale * max(0.0, load - load_thresh))
    bonus = w_type * c * (1.0 + 0.5 * max(0.0, load - load_thresh))
    bonus += w_weight * task.weight
    if task.tenant == 'premium':
        bonus += w_tenant
    if slack < 0:
        return -penalty + bonus + w_spt / p
    return -slack + bonus
