import math
def priority(task, state, k=1.0, m=2.0, c_align=1.0, c_sv=3.0, c_var=5.0,
             alpha=0.5, qlen_ref=10.0, overdue=0.2, w=1.0):
    est = max(task.estimated_runtime, 1e-6)
    res = max(task.resource_need, 1e-6)
    if task.task_type == 'variant_calling':
        c = c_var
    elif task.task_type == 'sv_calling':
        c = c_sv
    else:
        c = c_align
    tier = m if task.tenant == 'premium' else 1.0
    slack = max(0.0, task.due - state.now - est)
    urgency = math.exp(-slack / (k * max(state.mean_est, 1e-6)))
