        urgency *= overdue
    pressure = state.queue_len / (state.queue_len + max(qlen_ref, 1e-6))
    size = (est ** (1.0 + alpha * pressure)) * (res ** (alpha * pressure))
    weight = max(task.weight, 1e-6) ** w
    return c * tier * weight * urgency / max(size, 1e-6)

