import math
def priority(task, state, a=0.5, k=1.0, safety=1.0, p_pow=1.0, r_pow=0.0, load_pow=0.0):
    p = max(task.estimated_runtime, 1e-6)
    r = max(task.resource_need, 1e-6)
    if task.task_type == 'variant_calling':
        s = 5.0
    elif task.task_type == 'sv_calling':
        s = 3.0
    else:
        s = 1.0
    mean = max(state.mean_est, 1e-6)
    cap = max(state.capacity, 1e-6)
    load = max(state.queue_work, 0.0) / max(cap * mean, 1e-6)
    scale = max(k * mean / (1.0 + load_pow * load), 1e-6)
    slack = task.due - state.now - safety * p
    x = -slack / scale
    if x > 60.0:
        x = 60.0
    elif x < -60.0:
        x = -60.0
    return (s ** a) * math.exp(x) / max(p ** p_pow, 1e-6) / max(r ** r_pow, 1e-6)
